<?php use Aibid\Http\View as V; ?>
<div class="page-heading"><div><span class="eyebrow">CATÁLOGO</span><h1>Productos</h1><p>Productos y capacidades disponibles para emitir licencias.</p></div><?php if ($actor->role==='superadmin'): ?><a href="/admin/products/new" class="btn btn-primary">＋ Nuevo producto</a><?php endif; ?></div>
<div class="row g-4"><?php foreach ($products as $product): ?><div class="col-xl-6"><section class="panel product-card"><div class="d-flex justify-content-between align-items-start"><div class="product-symbol" aria-hidden="true">◇</div><span class="tag <?= $product['state']==='active'?'tag-green':'' ?>"><?= $product['state']==='active'?'Activo':'Archivado' ?></span></div><?php if ($product['product_id']==='gestor_documental'): ?><img class="product-logo" src="/assets/brand/logo-h.svg" alt="AIBID"><?php else: ?><h2 class="mt-4"><?= V::escape($product['display_name']) ?></h2><?php endif; ?><p><?= V::escape($product['description']) ?></p><div class="product-footer"><span><?= (int) $product['license_count'] ?> licencias <small><?= V::escape($product['product_id']) ?></small></span><a class="text-link" href="/admin/products/<?= V::escape($product['product_id']) ?>">Ver producto →</a></div></section></div><?php endforeach; ?></div>
